<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute,useRouter}from'vue-router';import AuthorizationSubnav from'../components/AuthorizationSubnav.vue';import{useAuthorizationStore}from'../runtime/authorization-store';import type{AuthorizationRuleDraft,Weekday}from'../types';const route=useRoute(),router=useRouter(),store=useAuthorizationStore();const{options,plans,selectedRule,loading,saving}=storeToRefs(store);const id=computed(()=>String(route.params.ruleId??'')),editing=computed(()=>Boolean(id.value)),error=ref<string|null>(null);const draft=reactive<AuthorizationRuleDraft>({name:'',weekdays:[1],timeRanges:[{start:'08:00',end:'12:00'}],planId:'',customerIds:[]});const dayLabels=['周一','周二','周三','周四','周五','周六','周日'];function addRange(){draft.timeRanges.push({start:'13:00',end:'17:00'})}async function save(){error.value=null;try{editing.value?await store.updateRule(id.value,draft):await store.createRule(draft);await router.push('/products/authorizations/rules')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}onMounted(async()=>{await store.load('plans');if(editing.value){await store.loadRule(id.value);if(selectedRule.value)Object.assign(draft,{name:selectedRule.value.name,weekdays:[...selectedRule.value.weekdays],timeRanges:selectedRule.value.timeRanges.map(x=>({...x})),planId:selectedRule.value.planId,customerIds:[...selectedRule.value.customerIds]})}})</script>
<template><section class="auth-page"><header class="page-header"><div><p class="eyebrow">PRD-003 · 授权规则</p><h1>{{editing?'编辑授权规则':'新增授权规则'}}</h1></div><RouterLink class="button" to="/products/authorizations/rules">返回列表</RouterLink></header><AuthorizationSubnav/><div v-if="loading" class="state">正在加载规则资料…</div><form v-else class="form-card" @submit.prevent="save"><p v-if="error" class="warning">{{error}}</p><div class="form-grid"><label class="field"><span>规则名称 *</span><input v-model="draft.name" maxlength="20" required></label><label class="field"><span>授权方案 *</span><select v-model="draft.planId" required><option value="">请选择</option><option v-for="p in plans.items" :key="p.id" :value="p.id">{{p.name}}{{p.status==='disabled'?'（停用）':''}}</option></select></label><div class="field full"><span>生效周期：每周 *</span><div class="checks"><label v-for="(label,i) in dayLabels" :key="label"><input v-model="draft.weekdays" type="checkbox" :value="(i+1 as Weekday)">{{label}}</label></div></div><div class="field full"><span>生效时段 *</span><div v-for="(range,i) in draft.timeRanges" :key="i" class="range"><input v-model="range.start" type="time"><span>至</span><input v-model="range.end" type="time"><button v-if="draft.timeRanges.length>1" class="link danger" type="button" @click="draft.timeRanges.splice(i,1)">移除</button></div><button class="button" type="button" @click="addRange">新增时段</button><small class="hint">同日不可重叠、不跨日，结束分钟不再生效。</small></div><div class="field full"><span>客户范围 *</span><div class="checks"><label v-for="c in options.customers.filter(x=>x.status==='active')" :key="c.id"><input v-model="draft.customerIds" type="checkbox" :value="c.id">{{c.code}} · {{c.name}}</label></div></div></div><div class="form-actions"><RouterLink class="button" to="/products/authorizations/rules">取消</RouterLink><button class="button primary" :disabled="saving">保存</button></div></form></section></template><style scoped>@import './authorization-views.css';.range{display:flex;align-items:center;gap:8px;margin-bottom:8px}.range input{min-height:36px;padding:6px;border:1px solid var(--color-border-strong);border-radius:4px}</style>
